enum Message { Increment, FilterChanged(String) }
struct App { count: u32, filter: String }
fn update(state: &mut App, message: Message) -> Task<Message> {
    match message {
        Message::Increment => state.count += 1,
        Message::FilterChanged(f) => state.filter = f,
    }
    Task::none()
}
