struct CounterState { count: i32 }          // Clone + PartialEq
impl Reducible for CounterState {
    type Action = CounterAction;
    fn reduce(self: Rc<Self>, action: CounterAction) -> Rc<Self> {
        match action {
            CounterAction::Increment => Self { count: self.count + 1 }.into(),
            CounterAction::Reset => Self { count: 0 }.into(),
        }
    }
}
